#requires -Version 7.0
[CmdletBinding()]
param()

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$ToolRoot = Split-Path -Parent $PSCommandPath
$Inner = Join-Path $ToolRoot 'Invoke-GPIHub-V101-Target-Parity.ps1'
$Generated = Join-Path $ToolRoot 'Invoke-GPIHub-V101-Target-Parity-REV2.generated.ps1'

if (-not (Test-Path -LiteralPath $Inner -PathType Leaf)) {
    throw "Base V101 script missing: $Inner"
}

$text = Get-Content -LiteralPath $Inner -Raw
$pattern = '(?s)    \$TargetPrecheck = @''\r?\n.*?\r?\n''@\r?\n    \$pre = Invoke-SshScript'
$matches = [regex]::Matches($text,$pattern)
if ($matches.Count -ne 1) {
    throw "Expected exactly one V101 TargetPrecheck block; found $($matches.Count)."
}

$replacementB64 = ''
$replacement = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($replacementB64))
$replacementWithInvoke = $replacement + "`r`n    `$pre = Invoke-SshScript"
$generatedText = [regex]::Replace($text,$pattern,[System.Text.RegularExpressions.MatchEvaluator]{ param($m) $replacementWithInvoke },1)
Set-Content -LiteralPath $Generated -Value $generatedText -Encoding utf8 -NoNewline

$tokens = $null
$errors = $null
[System.Management.Automation.Language.Parser]::ParseFile($Generated,[ref]$tokens,[ref]$errors) | Out-Null
if ($errors.Count -gt 0) {
    $detail = ($errors | ForEach-Object { $_.Message }) -join '; '
    throw "Generated V101 REV2 parser validation failed: $detail"
}

Write-Host 'V101_REV2_INTERNAL_NETWORK_PRECHECK_PATCH=PASS' -ForegroundColor Green
Write-Host 'V101_REV2_GENERATED_PARSER=PASS' -ForegroundColor Green
Write-Host "Generated script: $Generated"

& pwsh.exe -NoProfile -ExecutionPolicy Bypass -File $Generated
exit $LASTEXITCODE
